def find_most_frequent_artist(songs):
    artist_counts = {}
    for song in songs:
        artist = song["artist"]
        artist_counts[artist] = artist_counts.get(artist, 0) + 1

    most_frequent_artists = [artist for artist, count in artist_counts.items() if count == max(artist_counts.values())]
    if len(most_frequent_artists) == 1:
        return most_frequent_artists[0]
    else:
        return most_frequent_artists

