def find_highest_average_sales(brands_data):
    highest_average = 0
    highest_brand = None

    for brand in brands_data:
        brand_average = sum(brand['sales']) / len(brand['sales'])
        if brand_average > highest_average:
            highest_average = brand_average
            highest_brand = brand['brand']

    return highest_brand

